def __attempt_ocr_on_scheduled_field_again(fieldName) -> object:
        CommonActions.press_key_sequence("<Up>")
        found_area = CommonActions.get_object_by_ocr_text_in_object(ROTreat.fieldsToBeScheduled_Available_Course_Fields_Pane, fieldName)
        if found_area is None:
            raise ValueError(f"Even after a second attempt to find the given field {fieldName} after moving the 'blue' highlight cursor. \
                The area was still not found using OCR")
        return found_area

