@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_course_prescription_by_name(courseName:str, ocrTolerance:float=0) -> None:
    """Locates the Treatment Session UI pane object > clicks the Course One Prescription Dropdown button >
    then finds the specified text in the Course One Prescription Dropdown window by OCR and selects it if found

    :params: courseName (str): the course name(i.e., the Rx Site name)
             ocrTolerance (float): the maximum allowed dissimilarity of OCR result. 0 means to use the actual course name
             to search directly instead of the text from OCR.
    """
    import difflib
    if __find_treatment_session_pane():
        CommonActions.left_click_object(ROTreat.insertSessionsTab_Course_One_Prescription_Dropdown)
        searchText = courseName
        if ocrTolerance > 0:
            textFound = CommonActions.get_all_text_via_ocr_in_object(ROTreat.insertSessionsTab_Course_One_Prescription_Dropdown_Window)
            max_sim = 0
            ocrText:str = ""
            for text in str(textFound).split("\n"):
                similarity = difflib.SequenceMatcher(None, text, courseName).ratio()
                if similarity > max_sim:
                    max_sim = similarity
                    ocrText = text
            if max_sim > 1 - ocrTolerance:
                searchText = ocrText
                print(f"Use the text obtained from OCR: {searchText} to match: {courseName}. The Similarity is: {max_sim}")
            else:
                print("No text found from OCR within the specified tolerance.")
        course_prescription_obj = CommonActions.get_object_by_ocr_text_in_object(ROTreat.insertSessionsTab_Course_One_Prescription_Dropdown_Window, searchText)
        if course_prescription_obj is not None:
            CommonActions.click_screen_area_object(course_prescription_obj)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def set_session_start_date(startDate: str) -> None:
    """Locates the Treatment Session UI pane object > clicks the Start Date text box > Clears it's contents >
    enters the given startDate paramter into the box. (Format of date should be Month/Day/Year [%m/%d/%Y])

    :param startDate: String variable of the start date that will be typed into the Start Date text box (Format = %m/%d/%Y)
    :type startDate: str
    :raises RuntimeError: This is raised if the Start Date text box is in an disabled state. This is likely due to the For Course radio button not being set to true.
    """
    if __find_treatment_session_pane():
        start_date_object_def = None
        try:
            CommonActions.find_object(ROTreat.insertSessionsTab_Start_Date_TextBox_alternate_id)
            start_date_object_def = ROTreat.insertSessionsTab_Start_Date_TextBox_alternate_id
        except FailedToFindObject:
            try:
                # Try the other object definition with a different object ID
                CommonActions.find_object(ROTreat.insertSessionsTab_Start_Date_TextBox)
                start_date_object_def = ROTreat.insertSessionsTab_Start_Date_TextBox
            except FailedToFindObject:
                raise RuntimeError("Start Date text box is likley not in an enabled state. Please check the state of the 'For Course' radio button")

        CommonActions.left_click_object(start_date_object_def)
        CommonActions.time.sleep(1) # Select the date text field again in case it doesn't get clicked on first attempt
        CommonActions.left_click_object(start_date_object_def)
        CommonActions.press_key_sequence("<Shift+Ctrl+a>")
        CommonActions.press_delete_key()
        CommonActions.type_in_textfield(start_date_object_def, startDate)
