def __find_obj_by_ocr_with_special_characters(searchText: str, restrictOcrToList: bool = False, timeout: int = 3000) -> opt[object]:
    """Helper function to append a special character that is typically added to a text string
    found when using OCR to search for a text string (e.g. date) in the session list pane in
    the Treatment Chart window. Tries to find the searched text string with several variations
    of appended special characters.

    Returns the object using OCR if the searchText is found in the Treatment Chart window.

    -> Hidden function that should not be used outside the context of the ro_treat.py file context!

    :param str searchText: Text string to search for in the Treatment Chart window
    :param bool restrictOcrToList: Restrict the OCR search to the session list pane only
    :return: Found object or None if not found
    :rtype: object
    """

    # Note: OCR sometimes misidentifies the vertical line as some obscure characters next to the text found in the Treatment Chart window
    possible_postfix_list = ["", "]", "}", "|", ")"]
    if restrictOcrToList:
        search_area_obj = ROTreat.Treament_session_pane_on_main_mosaiq_323
    else:
        search_area_obj = ROTreat.Main_Window

    for postfix in possible_postfix_list:
        # Try appending a common character to the searched text string
        try:
            found_session_obj = CommonActions.get_object_by_ocr_text_in_object(search_area_obj, searchText + postfix, timeout)
        except FailedToFindObject:
            found_session_obj = CommonActions.get_object_by_ocr_text_in_object(ROTreat.Treament_session_pane_on_main, searchText + postfix, timeout)
        if found_session_obj is not None:
            return found_session_obj
    return None


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_treatment_session_ocr_available() -> bool:
    """Reports whether OCR can read dates in the treatment session list.

    select_session_by_date_text() matches a date by OCR against the session list -- a Clarion
    control that exposes no row objects to query directly -- and Squish ships no OCR engine;
    Tesseract is a separate install. Probe with this first: without an engine,
    get_object_by_ocr_text_in_object() swallows the "tesseract not configured" error and
    returns None, so select_session_by_date_text() ends up clicking a None match, which raises
    a cryptic low-level error instead of a clear one.

    :return: True or False
    :rtype: bool
    """
    if not __find_main_window():
        return False
    return CommonActions.is_ocr_available(ROTreat.Main_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_session_by_date_text(treatmentDate: str, sessionSelectRetries: int = 5,
                                setDefaultSelectionToStart: bool = True, restrictOcrSearchToList: bool = True) -> None:
    """Locates the main RO Treat/ Treatment Chart window > then clicks the session if
    the treatmentDate text has been found

    NOTE: For Mosaiq 3.2.2 the restrictOcrSearchToList arg needs to be set to False. For Mosaiq 3.2.3 set to True

    :param str treatmentDate: Date string of the session to select
    :param int sessionSelectRetries: Number of times to scroll down the session list
    :param bool setDefaultSelectionToStart: Set the default selection to the first session in the list
    :param bool restrictOcrSearchToList: Restrict the OCR search to the session list pane only. This can be enabled for
                                         improved robustness if the treatmentDate search text is found more than once,
                                         for instance in the main Treatment Session pane as well as the Session List pane.
    """
    if __find_treatment_session_pane_on_main():
        try:
            if setDefaultSelectionToStart:
                CommonActions.press_home_key()
            session_obj = __find_obj_by_ocr_with_special_characters(treatmentDate, restrictOcrSearchToList)
            CommonActions.click_screen_area_object(session_obj)
        except SyntaxError:
            # Try scrolling down the session list by pressing the Pg Down keyboard button
            # a number of times as specified by sessionSelectRetries
            for i in range(sessionSelectRetries):
                try:
                    CommonActions.press_page_down_key()
                    session_obj = __find_obj_by_ocr_with_special_characters(treatmentDate, restrictOcrSearchToList)
                    CommonActions.click_screen_area_object(session_obj)
                    break
                except SyntaxError:
                    pass

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_treat_button(machineQaOverride: bool = False, machineQaOverridePassword: str = "impac",
                       continueTrtReadinessCheck: bool = True, ackVerifyImageStatus: bool = True) -> None:
    """Locates the main RO Treat window > then clicks on the Treat button >
    return true if the Treatment Delivery Table is window displayed

    :param bool machineQaOverride: Check if the Machine QA Override window appears and override
    :param str machineQaOverridePassword: Password to enter in the Machine QA Override window
    :param bool continueTrtReadinessCheck: Select the continue button on the Treatment Readiness Check
                                           window if shown
    :param bool ackVerifyImageStatus: Select the OK button on the Verification Image Status window
                                      if shown
    """
    if __find_main_window():
        CommonActions.left_click_object(ROTreat.Treat_Button)
        # Select the Override checkbox, enter approval password and select OK button
        # in the Machine QA Override window if it appears
        if machineQaOverride:
            MosaiqCommonPopups.machine_qa_override_approval(password=machineQaOverridePassword)
        # Select the Continue button on the Treatment Readiness Check window if shown
        if continueTrtReadinessCheck:
            MosaiqCommonPopups.click_continue_button_on_treatment_readiness()
        # Select OK button on Verification Image Status window if shown
        if ackVerifyImageStatus:
            MosaiqCommonPopups.click_on_ok_button_on_verify_image_window()
        CommonActions.wait_for_object_to_appear(ROTreat.treatment_Delivery_Table_Window)

