@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_first_session_in_tx_calendar() -> None:
    """Selects the first session row in the treatment calendar.

    The OCR-free alternative to select_session_by_date_text(): the session list is a Clarion
    control that publishes no row objects, so matching a date means reading the table by OCR,
    which needs a Tesseract engine and can misread the digits. Home selects the first row
    whatever it says.

    The list is clicked first so the keystroke lands on it -- pressing Home without focus does
    nothing. The click itself selects whichever row sits under the centre of the pane; Home then
    moves the selection to the top.

    Note this selects the FIRST session in the calendar, which is not necessarily today's or an
    untreated one. Use select_session_by_date_text() where the session matters.
    """
    if __find_treatment_session_pane_on_main():
        CommonActions.left_click_object(ROTreat.Treatment_Session_Pane)
        CommonActions.press_home_key()

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def is_ro_treat_open(waitTimeout: int = 30000) -> bool:
    """Reports whether the RO Treat / Treatment Chart window is open.

    The public counterpart to __find_main_window(), built on does_object_exist() rather than
    find_object(), whose missing-object fallback returns the first Edit in the AUT and so can
    never report absence.

    :param int waitTimeout: Time in milliseconds to wait before reporting the window absent
    :return: True or False
    :rtype: bool
    """
    return CommonActions.does_object_exist(ROTreat.Main_Window, waitTimeout)

